    abstract approval: U2<bool, (ActionConfig.Approval.Args<'InputSchema> -> U2<bool, JS.Promise<bool>>)> option with get, set
    abstract approvalSummary: string option with get, set
    abstract approvalRisk: ActionConfig.ApprovalRisk option with get, set
    abstract timeoutMs: float option with get, set
    abstract kind: ActionKind option with get, set
    abstract execute: input: obj * ctx: ActionContext -> U2<'Output, JS.Promise<'Output>>
