    abstract classification: ChatErrorClassification option with get, set
    [<ParamObject; Emit("$0")>]
    static member Create (stage: ChatErrorContext.Stage, ?requestId: string, ?messagesPersisted: bool, ?classification: ChatErrorClassification) : ChatErrorContext = jsNative

/// <summary>
/// Context passed to the <c>beforeStep</c> hook before each AI SDK step in
/// the agentic loop. Backed by the AI SDK's <c>PrepareStepFunction&lt;TOOLS&gt;</c>
/// parameter — exposes the previous <c>steps</c>, the zero-based <c>stepNumber</c>,
/// the currently selected <c>model</c>, the <c>messages</c> about to be sent, and
/// <c>experimental_context</c>.
/// <br /><br />
/// Pass an explicit <c>TOOLS</c> generic for typed previous tool calls / results.
/// <br /><br />
/// Limitations (AI SDK boundary, not Think):
/// - No <c>abortSignal</c> is exposed in the context. If you do remote work
///   inside <c>beforeStep</c>, it cannot be cancelled by turn-level abort.
/// - <c>experimental_context</c> is typed <c>unknown</c>; users must narrow it.
/// - <c>output</c> cannot be overridden per-step — set it at the turn level
///   via <c>TurnConfig.output</c> (returned from <c>beforeTurn</c>).
/// </summary>
[<Interface>]
type PrepareStepContext =
    /// <summary>
    /// The steps that have been executed so far.
    /// </summary>
    abstract steps: obj[] with get, set
    /// <summary>
    /// The number of the step that is being executed.
    /// </summary>
    abstract stepNumber: float with get, set
    /// <summary>
    /// The model instance that is being used for this step.
    /// </summary>
    abstract model: obj with get, set
    /// <summary>
    /// The instructions that will be sent to the model for the current step.
    /// </summary>
    abstract instructions: obj option with get, set
    /// <summary>
    /// The initial instructions that were passed into generateText or streamText.
    /// </summary>
    abstract initialInstructions: obj option with get, set
    /// <summary>
    /// The messages that will be sent to the model for the current step.
    /// If you return a <c>messages</c> override, those messages carry forward to later steps.
    /// </summary>
    abstract messages: obj[] with get, set
    /// <summary>
    /// The initial messages that were passed into generateText or streamText.
    /// </summary>
    abstract initialMessages: obj[] with get, set
    /// <summary>
    /// The response messages that have been accumulated from all previous steps.
    /// </summary>
    abstract responseMessages: obj[] with get, set
    /// <summary>
    /// Tool context.
    /// </summary>
    abstract toolsContext: obj with get, set
    /// <summary>
    /// User-defined runtime context.
    /// </summary>
    abstract runtimeContext: Record<string, obj> with get, set
    /// <summary>
    /// The sandbox environment that the step is operating in.
    /// </summary>
    abstract experimental_sandbox: obj option with get, set
    [<ParamObject; Emit("$0")>]
    static member Create (steps: obj[], stepNumber: float, model: obj, messages: obj[], initialMessages: obj[], responseMessages: obj[], toolsContext: obj, runtimeContext: Record<string, obj>, ?instructions: obj, ?initialInstructions: obj, ?experimental_sandbox: obj) : PrepareStepContext = jsNative

/// <summary>
/// Configuration returned by <c>beforeStep</c> to override defaults for the
/// current AI SDK step. This is the AI SDK's <c>PrepareStepResult&lt;TOOLS&gt;</c> —
/// return only the fields you want to override (<c>model</c>, <c>toolChoice</c>,
/// <c>activeTools</c>, <c>instructions</c>, <c>messages</c>, <c>experimental_context</c>,
/// <c>providerOptions</c>). The previous <c>system</c> field remains available as a
/// deprecated alias.
/// <br /><br />
/// <c>model</c> is widened to ThinkModel: like Think.getModel, you
/// can return a model id string (resolved via the built-in provider) instead of
/// a <c>LanguageModel</c>. Think resolves it before handing the step to the AI SDK.
/// </summary>
[<Interface>]
type StepConfig<'TOOLS> =
    abstract model: ThinkModel option with get, set
    [<ParamObject; Emit("$0")>]
    static member Create (?model: ThinkModel) : StepConfig<'TOOLS> = jsNative

/// <summary>
/// Context passed to the <c>beforeToolCall</c> hook <b>before</b> the tool's
/// <c>execute</c> function runs.
/// <br /><br />
/// Backed by the AI SDK's <c>OnToolCallStartEvent</c> (the parameter of
/// <c>experimental_onToolCallStart</c>). The full <c>TypedToolCall&lt;TOOLS&gt;</c>
/// fields (<c>toolName</c>, <c>toolCallId</c>, <c>input</c>, <c>providerMetadata</c>, the
/// dynamic/invalid/error discriminators) are spread at the top level for
/// convenience, with the per-call event extras attached:
/// <br /><br />
/// - <c>stepNumber</c> — index of the current step
/// - <c>messages</c>   — conversation messages visible at tool execution time
/// - <c>abortSignal</c> — signal that aborts if the turn is cancelled
/// <br /><br />
/// Pass an explicit <c>TOOLS</c> generic for full input typing. With a concrete
/// tool set, narrowing on <c>ctx.toolName</c> narrows <c>ctx.input</c> to that tool's
/// input shape:
/// <code lang="ts">
/// import type { ToolCallContext } from "@cloudflare/think";
/// import type { tools } from "./my-tools";
///
/// beforeToolCall(ctx: ToolCallContext&lt;typeof tools&gt;) {
///   if (ctx.toolName === "search") {
///     ctx.input.query; // typed as string
///   }
/// }
/// </code>
/// </summary>
[<Erase>]
type ToolCallContext<'TOOLS> = private ToolCallContext__ of obj

[<RequireQualifiedAccess; TypeScriptTaggedUnion("action", CaseRules.None)>]
type ToolCallDecision =
    | [<CompiledName("allow")>] Allow of input: Record<string, obj> option
    | [<CompiledName("block")>] Block of reason: string option
    | [<CompiledName("substitute")>] Substitute of output: obj * input: Record<string, obj> option

/// <summary>
/// Context passed to the <c>afterToolCall</c> hook after a tool executes.
/// <br /><br />
/// Backed by the AI SDK's <c>OnToolExecutionEndEvent</c>. The full
/// <c>TypedToolCall&lt;TOOLS&gt;</c> fields (<c>toolName</c>, <c>toolCallId</c>, <c>input</c>, …) are
/// spread at the top level, plus the per-call event extras:
/// <br /><br />
/// - <c>stepNumber</c>  — index of the current step
/// - <c>messages</c>    — conversation messages visible at tool execution time
/// - <c>toolExecutionMs</c> — wall-clock execution time in milliseconds
/// - <c>durationMs</c>  — deprecated alias for <c>toolExecutionMs</c>
/// - <c>toolOutput</c> — AI SDK v7 discriminated outcome
/// - <c>success</c>/<c>output</c>/<c>error</c> — deprecated normalized outcome aliases:
///   - on success: <c>success: true</c>, <c>output</c> typed per tool
///   - on failure: <c>success: false</c>, <c>error: unknown</c>
/// <br /><br />
/// Pass an explicit <c>TOOLS</c> generic for full input <b>and</b> output typing.
/// On the success branch, narrowing on <c>ctx.toolName</c> narrows <c>ctx.output</c>
/// to that tool's inferred output type (dynamic tools stay <c>unknown</c>):
/// <code lang="ts">
/// import type { ToolCallResultContext } from "@cloudflare/think";
/// import type { tools } from "./my-tools";
///
/// afterToolCall(ctx: ToolCallResultContext&lt;typeof tools&gt;) {
///   if (ctx.toolName === "search" &amp;&amp; ctx.success) {
///     ctx.output.results; // typed as the `search` tool's output
///   }
/// }
/// </code>
/// </summary>
[<Erase>]
type ToolCallResultContext<'TOOLS> = private ToolCallResultContext__ of obj

/// <summary>
/// Context passed to the <c>onStepFinish</c> hook after each step completes.
/// <br /><br />
/// This is the AI SDK's <c>StepResult&lt;TOOLS&gt;</c> (= <c>OnStepFinishEvent&lt;TOOLS&gt;</c>) —
/// the full step record including <c>text</c>, <c>reasoning</c>, <c>toolCalls</c>,
/// <c>toolResults</c>, <c>files</c>, <c>sources</c>, <c>usage</c> (with <c>cachedInputTokens</c>,
/// <c>reasoningTokens</c>, <c>totalTokens</c>), <c>finishReason</c>, <c>warnings</c>, <c>request</c>,
/// <c>response</c>, and <c>providerMetadata</c> (where provider-specific cache
/// accounting like <c>cacheCreationInputTokens</c> lives).
/// <br /><br />
/// Pass an explicit <c>TOOLS</c> generic for typed <c>toolCalls</c>/<c>toolResults</c>.
/// </summary>
[<Erase>]
type StepContext<'TOOLS> = private StepContext__ of obj

/// <summary>
/// Context passed to the <c>onChunk</c> hook for each streaming chunk.
/// <br /><br />
/// This is the AI SDK's <c>StreamTextOnChunkCallback</c> event — <c>{ chunk }</c>
/// where <c>chunk</c> is a discriminated union of <c>TextStreamPart</c> variants
/// (text-delta, reasoning-delta, source, tool-call, tool-input-start,
/// tool-input-delta, tool-result, raw).
/// </summary>
[<Interface>]
type ChunkContext =
    abstract chunk: obj with get, set
    [<ParamObject; Emit("$0")>]
    static member Create (chunk: obj) : ChunkContext = jsNative

/// <remarks>
/// @internal
/// Re-export of the chunk variant union for consumers that need
/// to narrow on <c>chunk.type</c> without importing <c>TextStreamPart</c> directly.
/// </remarks>
[<Erase>]
type ChunkPart<'TOOLS> = private ChunkPart__ of obj

/// <summary>
/// Configuration for a sandboxed extension, returned by getExtensions().
/// </summary>
[<Interface>]
type ExtensionConfig =
    /// <summary>
    /// Extension manifest (name, version, permissions, contributions).
    /// </summary>
    abstract manifest: Extensions.ExtensionManifest with get, set
    /// <summary>
    /// JavaScript source code defining the extension's tools.
    /// </summary>
    abstract source: string with get, set
    [<ParamObject; Emit("$0")>]
    static member Create (manifest: Extensions.ExtensionManifest, source: string) : ExtensionConfig = jsNative

/// <summary>
/// A model id accepted by Think.getModel.
/// <br /><br />
/// Provides editor autocomplete for the Workers AI text-generation catalog
/// (<c>@cf/...</c>) while still accepting <b>any</b> string — including
/// <c>"&lt;provider&gt;/&lt;model&gt;"</c> AI Gateway slugs like <c>"openai/gpt-5.5"</c>, whose
/// validity is only known at runtime (the catalog is server-side and changes
/// independently of these types). The <c>(string &amp; {})</c> arm is what keeps
/// arbitrary strings assignable without collapsing the autocomplete union.
/// </summary>
type ThinkModelId = string

/// <summary>
/// What Think.getModel may return: either a fully-constructed AI SDK
/// <c>LanguageModel</c>, or a ThinkModelId string resolved through Think's
/// built-in <c>workers-ai-provider</c>. Also the input type of Think.resolveModel.
/// </summary>
type ThinkModel = obj

[<Interface>]
[<Import("Think", "@cloudflare/think")>]
type Think<'Env, 'State, 'Props> =
    /// <summary>
    /// Runtime lifecycle and reusable durable capabilities for this Agent.
    /// </summary>
    /// <remarks>@experimental The API surface may change before stabilizing.</remarks>
    abstract lifecycle: obj
    /// <summary>
    /// Run user initialization after lifecycle components have started.
    /// </summary>
    abstract onStart: ?_props: 'Props -> JS.Promise<unit> option
    /// <summary>
    /// Handle an HTTP request not claimed by a lifecycle component.
    /// </summary>
    abstract onRequest: _request: obj -> obj
    /// <summary>
    /// Handle a newly accepted hibernating WebSocket connection.
    /// </summary>
    abstract onConnect: _connection: Think.OnConnect.Connection<obj> * _context: obj -> JS.Promise<unit> option
    /// <summary>
    /// Handle a message from a hibernating WebSocket connection.
    /// </summary>
    abstract onMessage: _connection: Think.OnConnect.Connection<obj> * _message: U3<string, JS.ArrayBuffer, JS.ArrayBufferView> -> JS.Promise<unit> option
    /// <summary>
    /// Handle a hibernating WebSocket connection closing.
    /// </summary>
    abstract onClose: _connection: Think.OnConnect.Connection<obj> * _code: float * _reason: string * _wasClean: bool -> JS.Promise<unit> option
    /// <summary>
    /// Return tags persisted with a hibernating WebSocket connection.
    /// </summary>
    abstract getConnectionTags: _connection: Think.OnConnect.Connection<obj> * _context: obj -> U2<string[], JS.Promise<string[]>>
    /// <remarks>@internal Ensure lifecycle startup before a native RPC implementation.</remarks>
    abstract __unsafe_ensureInitialized: ?props: 'Props -> JS.Promise<unit>
    abstract _state: obj with get, set
    abstract _disposables: obj with get, set
    abstract _destroyed: obj with get, set
    /// <summary>
    /// Stores raw state accessors for wrapped connections.
    /// Used by internal flag methods (readonly, no-protocol) to read/write
    /// _cf_-prefixed keys without going through the user-facing state/setState.
    /// </summary>
    abstract _rawStateAccessors: obj with get, set
    /// <summary>
    /// Cached persistence-hook dispatch mode, computed once in the constructor.
    /// - "new"  → call onStateChanged
    /// - "old"  → call onStateUpdate (deprecated)
    /// - "none" → neither hook is overridden, skip entirely
    /// </summary>
    abstract _persistenceHookMode: obj with get, set
    /// <summary>
    /// True when this agent runs as a facet (sub-agent) inside a parent.
    /// </summary>
    abstract _isFacet: obj with get, set
    abstract _protocolBroadcastExcludeIds: obj with get, set
    abstract _cf_subAgentBridgeContext: obj with get, set
    abstract _cf_virtualSubAgentConnections: obj with get, set
    abstract _cf_subAgentConnectionOperationTails: obj with get, set
    abstract _cf_subAgentBroadcastOperationTail: obj option with get, set
    /// <summary>
    /// User-facing facet name. For legacy facets this is the same as
    /// <c>ctx.id.name</c>; path-scoped facets use an internal routing id and
    /// keep the logical name here instead.
    /// </summary>
    /// <remarks>@internal</remarks>
    abstract _facetName: obj option with get, set
    /// <summary>
    /// Ancestor chain, root-first. Empty for top-level DOs; populated at
    /// facet init time from the parent's own <c>selfPath</c>. Exposed publicly
    /// via the <c>parentPath</c> getter.
    /// </summary>
    /// <remarks>@internal</remarks>
    abstract _parentPath: obj with get, set
    /// <summary>
    /// Warn-once guard: <c>chatRecovery</c> reassigned during onStart() (too late for wake recovery).
    /// </summary>
    abstract _warnedChatRecoveryInOnStart: obj with get, set
    /// <summary>
    /// Number of active keepAlive() callers. When &gt; 0, <c>_rearmAlarm()</c>
    /// caps the next alarm at <c>keepAliveIntervalMs</c> so the DO stays alive.
    /// Purely in-memory — lost on eviction, which is correct because the
    /// in-memory work keepAlive was protecting is also lost.
    /// </summary>
    /// <remarks>@internal</remarks>
    abstract _keepAliveRefs: float with get, set
    /// <summary>
    /// In-memory tokens for keepAlive leases acquired by facets and held
    /// on the root alarm owner. Lost on eviction, like <c>_keepAliveRefs</c>,
    /// because the in-memory work those leases were protecting is also gone.
    /// </summary>
    /// <remarks>@internal</remarks>
    abstract _facetKeepAliveTokens: obj with get, set
    /// <remarks>@internal In-memory set of fiber IDs running in this process.</remarks>
    abstract _runFiberActiveFibers: obj with get, set
    /// <remarks>@internal In-memory abort controllers for managed running fibers.</remarks>
    abstract _managedFiberAbortControllers: obj with get, set
    /// <remarks>@internal In-memory executions for callers that want to await accepted work.</remarks>
    abstract _managedFiberExecutions: obj with get, set
    /// <remarks>@internal In-memory waiters for managed fibers reaching terminal ledger state.</remarks>
    abstract _managedFiberTerminalWaiters: obj with get, set
    /// <remarks>@internal Prevents re-entrant recovery from overlapping alarm ticks.</remarks>
    abstract _runFiberRecoveryInProgress: obj with get, set
    /// <remarks>
    /// @internal
    /// Consecutive runFiber-recovery scans that made NO forward progress
    /// while work was still pending. Drives the exponential backoff of the
    /// recovery follow-up alarm so a repeatedly-throwing recovery hook does not
    /// busy-loop the DO. Reset to 0 whenever a scan recovers anything.
    /// </remarks>
    abstract _recoveryNoProgressScans: obj with get, set
    /// <remarks>@internal Single-flight background recovery for parent agent-tool rows.</remarks>
    abstract _agentToolRunRecoveryPromise: obj with get, set
    /// <remarks>@internal Serializes detached-backbone arming against concurrent dispatch.</remarks>
    abstract _detachedBackboneArming: obj with get, set
    /// <remarks>@internal Edge-trigger latch for the live-detached-count warning.</remarks>
    abstract _detachedLiveCountWarned: obj with get, set
    abstract _ParentClass: obj with get, set
    /// <summary>
    /// Durable scheduling capability installed into this Agent's Lifecycle.
    /// </summary>
    /// <remarks>
    /// @experimental
    /// The API surface may change before stabilizing. Agent's
    /// schedule()/scheduleEvery()/getScheduleById()/listSchedules()/
    /// cancelSchedule() methods are the stable surface.
    /// </remarks>
    abstract scheduler: obj
    abstract mcp: obj
    /// <summary>
    /// Initial state for the Agent
    /// Override to provide default state values
    /// </summary>
    abstract initialState: 'State with get, set
    /// <summary>
    /// Stable key for Workers AI session affinity (prefix-cache optimization).
    /// <br /><br />
    /// Uses the Durable Object ID, which is globally unique across all agent
    /// classes and stable for the lifetime of the instance. Pass this value as
    /// the <c>sessionAffinity</c> option when creating a Workers AI model so that
    /// requests from the same agent instance are routed to the same backend
    /// replica, improving KV-prefix-cache hit rates across conversation turns.
    /// </summary>
    /// <example>
    /// <code>
    /// ```typescript
    /// const workersai = createWorkersAI({ binding: this.env.AI });
    /// const model = workersai("@cf/meta/llama-3.3-70b-instruct-fp8-fast", {
    ///   sessionAffinity: this.sessionAffinity,
    /// });
    /// </code>
    /// <code>
    /// </code>
    /// </example>
    abstract sessionAffinity: string
    /// <summary>
    /// Current state of the Agent
    /// </summary>
    abstract state: 'State
    /// <summary>
    /// Resolved options (merges defaults with subclass overrides).
    /// Cached after first access — static options never change during the
    /// lifetime of a Durable Object instance.
    /// </summary>
    abstract _cachedOptions: obj option with get, set
    abstract _resolvedOptions: obj
    /// <summary>
    /// The observability implementation to use for the Agent
    /// </summary>
    abstract observability: obj option with get, set
    /// <summary>
    /// Emit an observability event with auto-generated timestamp.
    /// </summary>
    /// <remarks>@internal</remarks>
    abstract _emit: ``type``: Think.Emit.Type * ?payload: Record<string, obj> -> unit
    /// <summary>
    /// Run SDK work under a stable parent for platform child spans.
    /// </summary>
    abstract _withAgentSpan: obj with get, set
    /// <summary>
    /// Execute SQL queries against the Agent's database
    /// </summary>
    /// <remarks>@template T Type of the returned rows</remarks>
    /// <param name="strings">SQL query template strings</param>
    /// <param name="values">Values to be inserted into the query</param>
    /// <returns>Array of query results</returns>
    abstract sql<'T>: strings: obj * [<ParamArray>] values: U3<string, float, bool> option[] -> 'T[]
    abstract _schemaInitialization: obj with get, set
    /// <summary>
    /// Create all internal tables and run migrations if needed.
    /// Called by the constructor on every wake. Idempotent — skips DDL when
    /// the stored schema version matches CURRENT_SCHEMA_VERSION.
    /// <br /><br />
